<template>
  <div class="scores-page"><div class="breadcrumb"><button type="button" @click="router.push(`/teacher/course/${courseId}/workspace`)">课程首页</button><span>›</span><strong>成绩查看</strong></div><header class="heading"><div><p>SCORE OVERVIEW</p><h1>成绩查看</h1><span>{{ course?.name || '当前课程' }} · 按作业查看学生个人成绩</span></div></header><div v-if="errorMessage" class="error-box">{{ errorMessage }}</div><div class="assignment-tabs"><button v-for="assignment in assignments" :key="assignment.id" type="button" :class="{active: selectedId === assignment.id}" @click="selectAssignment(assignment.id)">{{ assignment.title }}</button></div><section v-if="selectedAssignment" class="panel"><div class="panel-head"><div><h2>{{ selectedAssignment.title }}</h2><span>团队成绩经过 MCQS 计算后生成个人成绩；未发布成绩不会对学生生效</span></div><div class="stats"><b>{{ scoredCount }}</b><small>/ {{ scores.length }} 已有成绩</small></div></div><div class="toolbar"><div class="search"><el-icon><Search /></el-icon><input v-model="keyword" placeholder="搜索学生姓名或学号" /></div><span>显示 {{ filteredScores.length }} 人</span></div><div v-if="loading" class="loading">正在加载成绩…</div><el-empty v-else-if="!filteredScores.length" description="暂无成绩记录" /><table v-else><thead><tr><th>学生</th><th>团队</th><th>团队成绩</th><th>贡献比例</th><th>个人成绩</th><th>状态</th></tr></thead><tbody><tr v-for="student in filteredScores" :key="student.studentId"><td><strong>{{ student.name || '未命名' }}</strong><small>{{ student.studentNo }}</small></td><td>{{ student.groupName || '未分组' }}</td><td>{{ displayScore(student.groupScore) }}</td><td>{{ displayRatio(student.contributionRatio) }}</td><td class="final-score">{{ displayScore(student.individualFinalScore ?? student.finalScore) }}</td><td><i :class="student.scorePublished ? 'published' : 'unpublished'">{{ student.scorePublished ? '已发布' : '未发布' }}</i></td></tr></tbody></table></section><el-empty v-else description="当前课程暂无作业" /></div>
  <div class="pagination-bar" v-if="selectedAssignment && pageCount > 1"><button type="button" :disabled="page <= 1" @click="page--">上一页</button><span>第 {{ page }} / {{ pageCount }} 页</span><button type="button" :disabled="page >= pageCount" @click="page++">下一页</button></div>
</template>
<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElEmpty, ElIcon } from 'element-plus'
import { Search } from '@element-plus/icons-vue'
import { getAssignments, getCourses, getTeacherScores } from '@/api/teacher'
import { getErrorMessage } from '@/api/response'
const route = useRoute(); const router = useRouter(); const courseId = route.params.courseId; const courses = ref([]); const assignments = ref([]); const scores = ref([]); const selectedId = ref(null); const keyword = ref(''); const page = ref(1); const pageSize = 8; const loading = ref(false); const errorMessage = ref('')
const course = computed(() => courses.value.find((item) => String(item.id) === String(courseId))); const selectedAssignment = computed(() => assignments.value.find((item) => item.id === selectedId.value)); const matchingScores = computed(() => scores.value.filter((item) => `${item.name || ''} ${item.studentNo || ''}`.toLowerCase().includes(keyword.value.toLowerCase()))); const pageCount = computed(() => Math.max(1, Math.ceil(matchingScores.value.length / pageSize))); const filteredScores = computed(() => matchingScores.value.slice((page.value - 1) * pageSize, page.value * pageSize)); const scoredCount = computed(() => scores.value.filter((item) => item.individualFinalScore != null || item.finalScore != null).length)
const displayScore = (value) => value == null ? '—' : Number(value).toFixed(2); const displayRatio = (value) => value == null ? '—' : `${(Number(value) * 100).toFixed(1)}%`
watch(keyword, () => { page.value = 1 })
const selectAssignment = async (id) => { selectedId.value = id; keyword.value = ''; page.value = 1; loading.value = true; try { scores.value = (await getTeacherScores(courseId, id)).map((item) => ({ ...item, individualFinalScore: item.individualFinalScore ?? item.finalScore ?? item.suggestedScore ?? item.modelScore ?? item.ruleScore })) } catch (error) { errorMessage.value = getErrorMessage(error, '成绩加载失败') } finally { loading.value = false } }
onMounted(async () => { try { [courses.value, assignments.value] = await Promise.all([getCourses(), getAssignments(courseId)]); if (assignments.value.length) await selectAssignment(assignments.value[0].id) } catch (error) { errorMessage.value = getErrorMessage(error, '课程成绩加载失败') } })
</script>
<style scoped>
.pagination-bar{display:flex;align-items:center;justify-content:center;gap:16px;margin:22px 0 0;color:#718096;font-size:14px}.pagination-bar button{min-width:76px;padding:9px 14px;border:1px solid #dce5ec;border-radius:5px;color:#52657a;background:#fff;cursor:pointer}.pagination-bar button:disabled{color:#b5c0ca;background:#f5f7f9;cursor:not-allowed}
.scores-page{max-width:1180px;margin:0 auto}.breadcrumb{display:flex;gap:8px;margin-bottom:24px;color:#8795a6;font-size:14px}.breadcrumb button{padding:0;border:0;background:none;color:inherit;cursor:pointer}.breadcrumb strong{color:#263b53}.heading{margin-bottom:26px}.heading p{margin:0 0 7px;color:#6bb58b;font-size:11px;letter-spacing:1.5px}.heading h1{margin:0 0 8px;color:#263b53;font-size:30px}.heading span{color:#8795a6;font-size:14px}.assignment-tabs{display:flex;gap:10px;margin-bottom:18px;overflow:auto}.assignment-tabs button{padding:11px 18px;border:1px solid #e2eaf0;border-radius:6px;color:#64748b;background:#fff;white-space:nowrap;cursor:pointer}.assignment-tabs button.active{border-color:#356798;color:#fff;background:#356798}.panel{overflow:hidden;border-radius:8px;background:#fff;box-shadow:0 2px 8px rgba(38,59,83,.05)}.panel-head{display:flex;align-items:center;justify-content:space-between;padding:20px 22px;border-bottom:1px solid #edf1f4}.panel-head h2{margin:0 0 7px;color:#263b53;font-size:19px}.panel-head span{color:#8795a6;font-size:12px}.stats{display:flex;align-items:baseline;gap:5px;color:#8795a6}.stats b{color:#356798;font-size:27px}.toolbar{display:flex;align-items:center;justify-content:space-between;padding:14px 22px}.toolbar>span{color:#8795a6;font-size:13px}.search{display:flex;align-items:center;gap:8px;width:260px;color:#9aa8b7}.search input{width:100%;border:0;outline:0;font-size:14px}table{width:100%;border-collapse:collapse;text-align:left}th{padding:13px 22px;color:#8795a6;background:#fafcfd;font-size:12px;font-weight:500}td{padding:15px 22px;border-top:1px solid #edf1f4;color:#52657a;font-size:13px}td strong,td small{display:block}td small{margin-top:4px;color:#98a5b3;font-size:11px}.final-score{color:#356798;font-size:16px;font-weight:600}.published,.unpublished{padding:4px 9px;border-radius:99px;font-size:12px;font-style:normal}.published{color:#35845a;background:#edf8f1}.unpublished{color:#9b6b29;background:#fff6e8}.loading{padding:30px;text-align:center;color:#8795a6}.error-box{margin-bottom:16px;padding:13px;border-radius:6px;color:#b42318;background:#fff5f5}@media(max-width:720px){.panel-head{align-items:flex-start;flex-direction:column;gap:14px}.search{width:100%}.toolbar{align-items:stretch;flex-direction:column;gap:12px}.panel{overflow-x:auto}table{min-width:760px}}
</style>
